#pragma once

#include "orbvi_sdk/status.hpp"
#include "orbvi_camera_contract/rig.hpp"
#include <array>
#include <string>

namespace orbvi_sdk {

// Mounting direction relative to the product's documented Front direction.
// This is not an optical-frame axis definition or a hardware channel number.
using FisheyeCameraRole = orbvi_camera_contract::Role;
using FisheyeCameraPlatform = orbvi_camera_contract::Platform;
using orbvi_camera_contract::ToString;

struct FisheyeCameraInput {
  int camera_id = -1;  // Product channel identity, not /dev/videoN or a module serial.
  FisheyeCameraRole role = FisheyeCameraRole::Unknown;
  // Single directory name under dataset/frames/ or dataset/ (legacy layout).
  // Distinct existing candidates are rejected; no slash, dot/dotdot or NUL.
  std::string image_directory;
};

struct FisheyeCalibrationOptions {
  // Read-only SDK capture: frames/<role>/<synchronized-key>.pgm (or png/jpeg).
  std::string dataset_directory;
  // Known platform derives all four IDs/roles/directories. Explicit inputs, if
  // supplied, must agree with that platform; Unknown requires explicit inputs.
  FisheyeCameraPlatform platform = FisheyeCameraPlatform::Unknown;
  // Required explicit bindings, in any order. All four roles and unique
  // nonnegative camera IDs are required. The SDK orders the solve by role.
  std::array<FisheyeCameraInput, 4> cameras;
  int target_columns = 11;
  int target_rows = 8;
  double square_size_mm = 50;
  // Even sampling over the complete sequence. 0 means all, at most 2000 sets.
  int max_images = 400;
};

struct FisheyeCameraCalibration {
  int camera_id = -1;
  FisheyeCameraRole role = FisheyeCameraRole::Unknown;
  // Generated by role: front=cam0, right=cam1, rear=cam2, left=cam3.
  std::string calibration_key;
  int width = 0;
  int height = 0;
  // Triple-sphere parameters: fx, fy, cx, cy, xi, lambda, alpha, b, c.
  std::array<double, 9> intrinsics{};
  // Row-major 4x4. T_A_B maps B into A. Translation unit: millimeter.
  // Rig is the front camera frame. Legacy Twc equals T_rig_camera.
  std::array<double, 16> T_rig_camera{};
  std::array<double, 16> T_camera_rig{};
  int detections = 0;
  double mean_reprojection_error_px = 0;
};

struct FisheyeCalibrationResult {
  FisheyeCameraPlatform platform = FisheyeCameraPlatform::Unknown;
  std::string source_dataset_directory;
  // Canonical input directories retained for save/input overlap protection.
  std::array<std::string, 4> source_image_directories;
  std::string tscm_revision;
  int target_columns = 0;
  int target_rows = 0;
  double square_size_mm = 0;
  int image_sets = 0;
  std::array<FisheyeCameraCalibration, 4> cameras;  // front, right, rear, left.
  std::array<int, 4> common_observations{};  // front-right, right-rear, rear-left, left-front.
  double mean_reprojection_error_px = 0;
};

// Synchronous CPU solve, no connection/device/IMU required. Link the SDK's
// calibration component. Does not modify images or persist any output.
// One solve at a time per loaded component; overlapping calls return ResourceLimit.
Result<FisheyeCalibrationResult> CalibrateFisheye(const FisheyeCalibrationOptions& options);

// Explicit local save to a NEW directory outside the input dataset/directories.
// Parent must exist. Never overwrites an existing path. Writes physical YAML,
// quality JSON and a camera-ID/revision manifest; NOT a board-installable bundle.
// Saving rejects altered role/key ordering. YAML contains complete identity bindings;
// the v2 manifest includes bindings and SHA-256 for YAML and quality JSON.
// On I/O failure, the incomplete new directory is retained for diagnosis.
Result<void> SaveFisheyeCalibration(const FisheyeCalibrationResult& result,
                                   const std::string& output_directory);

}  // namespace orbvi_sdk
